def fetch(user_id):
    """Return the avatar bytes, or None if the user has deleted their avatar.

    The CDN answers 404 for deleted avatars, which is expected. Any other
    HTTP or network error is still raised.
    """
    url = f"{os.environ['AVATAR_BASE_URL']}/{user_id}.png"
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read()
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise

